scripts.事件21_5.txt:
	Say("紫轩：杨大哥，你为什么对我这么好！我只是个……", 17);
	Say("杨影枫：紫轩，你一不在我身边，我便六神无主，在你命在旦夕的时候，我才发现你对我有多么重要，如果你醒不了的话，我……", 2);
	Say("紫轩：杨大哥……", 17);
	Say("杨影枫：紫轩，我不会让你再受到任何伤害了！等我完成了先父的遗愿，我们就抛开一切去芭蕉小筑，在那个花香蝶美的地方，你我品箫舞剑，做一对神仙眷侣，好吗？", 2);
	Say("紫轩：……", 17);
	Say("杨影枫：这么说你是答应了？", 3);
	Say("紫轩：可是，杨大哥，芭蕉小筑不是已经被烧毁了吗？", 16);
	Say("杨影枫：你不要担心，我自会重建芭蕉小筑，到时改名叫剑箫居，好不好？", 3);
	Say("紫轩：都怪我，都是我不好，我惹了这么多麻烦，让你唯一的栖身之所也没了……你义兄会不会因此怪你？", 17);
	Say("杨影枫：傻瓜，这又不是你的错！不要多想了，我先送你回家，然后去见义兄，向他讲明一切，他是通情达理之人，定会原谅我，然后请他给我们做媒，我就回来迎娶你，好不好？", 3);
	Say("紫轩：嗯！", 122);
//	Talk(3140, 3230);
	SetNpcKind("紫轩",3);
	SetNpcScript("紫轩", "紫轩对话.txt");
	
	
	Talk(20110, 20110);
	SetMapTrap(1, "Trap01.txt");
	AddToMemo(3240);
	Return;

scripts.乞丐对话.txt:
	GetRandNum($MoneyTalk, 1, 5);

	If ($SubEvent03 == 0) @SubEvent03;

	Say("乞丐：多行善事，才可能成为一代大侠。武功越高，越应该行侠仗义，这样才能以德服人。", 107);
//	Talk(20660, 20660);
	
	Goto @end;
	
@SubEvent03:

	If ($Sub03TalkTimes << 10) @Sub03GetMoney;
	If ($Sub03TalkTimes == 10) @Sub03GiveObj;

	Talk(20660, 20660);
	Goto @end;
	
@Sub03GetMoney:
	Say("乞丐：这位大侠，你行行好，给点儿钱吧。", 107);
	Choose("给乞丐８０两银子吗？", "给。", "不给。", $GiveMoney);
	If ($GiveMoney == 0) @GiveMoneyYes;
	If ($GiveMoney == 1) @GiveMoneyNo;
	@GiveMoneyYes:
		GetMoneyNum($TwentyMoney);
		If ($TwentyMoney >= 80) @GiveTwenty;
		Say("你没带这么多钱。");
		Goto @end;
		@GiveTwenty:
			If ($MoenyTalk == 1) @MoneyTalk01;
			If ($MoenyTalk == 2) @MoneyTalk02;
			If ($MoenyTalk == 3) @MoneyTalk03;
			If ($MoenyTalk == 4) @MoneyTalk04;
			If ($MoenyTalk == 5) @MoneyTalk05;
			@MoneyTalk01:
				Say("乞丐：大侠你真是少有的好人呀！", 107);
				Goto @MoneyTalk0End;
			@MoneyTalk02:
				Say("乞丐：好人会有好报的，谢谢大侠！", 107);
				Goto @MoneyTalk0End;
			@MoneyTalk03:
				Say("乞丐：菩萨保佑你荣华富贵、功名利禄、大吉大利、千秋万代！谢谢大侠！", 107);
				Goto @MoneyTalk0End;
			@MoneyTalk04:
				Say("乞丐：上至老祖，下至家小，对大侠的恩情都永生不忘！", 107);
				Goto @MoneyTalk0End;
			@MoneyTalk05:
				Say("乞丐：感恩戴德！感恩戴德！", 107);
				Goto @MoneyTalk0End;
			@MoneyTalk0End:
			AddMoney(-80);
			Add($Sub03TalkTimes, 1);
			Add($EvilVal, 5);
			Goto @end;
	@GiveMoneyNo:
		If ($MoenyTalk == 1) @MoneyTalk11;
		If ($MoenyTalk == 2) @MoneyTalk12;
		If ($MoenyTalk == 3) @MoneyTalk13;
		If ($MoenyTalk == 4) @MoneyTalk14;
		If ($MoenyTalk == 5) @MoneyTalk15;
		@MoneyTalk11:
			Say("杨影枫：看你也不拐不瘸的，养活自己总不是问题吧！", 2);
			Goto @end;
		@MoneyTalk12:
			Say("杨影枫：我怎么天天遇见你！", 2);
			Goto @end;
		@MoneyTalk13:
			Say("杨影枫：上回不是已经给过你！", 2);
			Goto @end;
		@MoneyTalk14:
			Say("杨影枫：象你这样的角儿我见得多了！", 2);
			Goto @end;
		@MoneyTalk15:
			Say("杨影枫：我可怜你，谁来可怜我呀！", 2);
			Goto @end;
		Goto @end;
	Goto @end;
@Sub03GiveObj:
	// 给主角物品
	Say("乞丐：这位大侠，你经常给我施舍，真是个好人呐！我这里捡到一本书，你知道我不识字儿留着也没用，大侠你走南闯北，兴许用得着，就送给你了！", 107);
	Choose("收下这本书吗？", "收下。", "不收。", $GetStone);
	If ($GetStone == 0) @GetStoneYes;
	If ($GetStone == 1) @GetStoneNo;
	@GetStoneYes:
		Say("杨影枫：如此多谢了！", 2);
		AddGoods("Book07-潮月剑法.ini");
		Add($Sub03TalkTimes, 1);
		Assign($SubEvent03, 10);
		Add($EvilVal, -40);
		Goto @end;
	@GetStoneNo:
		Say("杨影枫：我给你施舍，并不是为了让你报答，你还是留着吧！", 2);
		Add($Sub03TalkTimes, 1);
		Add($EvilVal, 10);
		Assign($SubEvent03, 10);
		Goto @end;
	Goto @end;
@end:
	Return;

scripts.炸药箱子.txt:
