scripts.中毒者对话.txt:
	If ($SubEvent15 == 0) @SubEvent1500;
	If ($SubEvent15 == 2) @SubEvent1502;
	If ($SubEvent15 == 5) @SubEvent1505;
	If ($SubEvent15 == 10) @SubEvent1510;
	Return;

@SubEvent1500:
	Say("章大爷：呃……哦……");
	Say("杨影枫：这位老丈，怎么啦？", 2);
	Say("章大爷：我……我好像中毒啦……我……");
	Say("杨影枫：啊！你不要急，我这就去找大夫，你在这里等着，我去去就回。", 8);
	Memo("去惠安镇找大夫给中毒者治病。");
	Assign($SubEvent15, 2);
	Add($EvilVal, -20);
	Return;

@SubEvent1502:
	Say("章大爷：我……我好像中毒啦……我……");
	Say("杨影枫：啊！你不要急，我这就去找大夫，你在这里等着，我去去就回。", 8);
	Return;

@SubEvent1505:
	Say("杨影枫：兄台，怎么样，这是药，“金山毒霸”，服下吧！", 2);
	Say("章大爷：嗯……谢谢公子！");
	Say("杨影枫：好些了吗？", 2);
	Say("章大爷：嗯，好些了，真是多谢公子！");
	Say("杨影枫：不用谢我，应该多谢大夫，多谢“金山毒霸”。", 3);
	DelGoods("Goods-e18-金山毒霸.ini");
	Assign($SubEvent15, 10);
	Add($EvilVal, 40);
	Return;

@SubEvent1510:
	Say("章大爷：“金山毒霸”真是好药啊！");
	Return;

scripts.小叁子对话.txt:
	If ($Event <> 232) @end;
	Say("小叁子：杨公子，这位就是我的表妹。你还有什么事吗？", 64);
	Say("杨影枫：没什么事，没什么事，你和你表妹慢慢聊吧，嘻嘻……", 3);
	Goto @end;
@end:
	Return;

scripts.阿亮他妈对话.txt:
	GetRandNum($ALiangTaMa, 1, 3);

	If ($SubEvent08 == 0) @SubEvent080;
	If ($SubEvent08 == 5) @SubEvent085;
	If ($SubEvent08 == 10) @SubEvent0810;
	If ($SubEvent08 == 20) @SubEvent0820;

@SubEvent080:
	Say("阿亮他妈：哎呀，我家阿亮怎么还不回来！这小子，一天到晚在外面玩，想找他帮我做点事连个人影也找不到。", 97);
	Say("杨影枫：大嫂，你的孩子不见了吗？要不要我帮你去找找？", 2);
	Say("阿亮他妈：如果公子能帮这个忙那真是太好了。他应该还在村子里玩，不会跑远的。", 97);
	Say("杨影枫：好的，我找到他，一定会叫他回家。", 2);
	Say("阿亮他妈：那可真是多谢公子啦！", 97);
	Memo("帮阿亮他妈找孩子。");
	Add($EvilVal, -10);
	Assign($SubEvent08, 5);
	Goto @end;
@SubEvent085:
	Say("阿亮他妈：公子，看见我儿子了吗？", 97);
	Say("杨影枫：大嫂，我正在找呢，很快就会找到的。", 2);
	Goto @end;
@SubEvent0820:
	Say("阿亮他妈：阿亮太不听话了，老是到处跑，待会儿回来非打他屁股不可。", 97);
	Goto @end;
@SubEvent0810:
	If ($Event == 164) @Event164166;
	If ($Event == 166) @Event164166;
	If ($Event == 168) @Event168;
	If ($Event == 170) @Event170;
	If ($Event == 230) @Event230;
	If ($Event == 231) @Event231232;
	If ($Event == 232) @Event231232;
	If ($Event == 370) @Event370;
	If ($Event == 375) @Event375;

		If ($ALiangTaMa == 1) @ALiangTaMa11;
		If ($ALiangTaMa == 2) @ALiangTaMa12;
		If ($ALiangTaMa == 3) @ALiangTaMa13;
		@ALiangTaMa11:
			Say("阿亮他妈：虽然我不能做什么大事，不过在这清平乡里住了半辈子，这里大姑大婶的事还没有什么我不知道的。", 97);
			Goto @end;
		@ALiangTaMa12:
			Say("阿亮他妈：自从有了阿亮这孩子，我就成天要操很多心！", 97);
			Goto @end;
		@ALiangTaMa13:
			Say("阿亮他妈：我家阿亮就象他爹，一天到晚往外头跑，真是没办法。", 97);
			Goto @end;
	@Event164166:
		Say("阿亮他妈：公子，听说本乡的紫轩姑娘跟你挺要好？", 97);
		Say("杨影枫：有缘相识。", 2);
		Say("阿亮他妈：哎呀公子，可不得了，紫轩姑娘她被人欺负了，你快去她家看看吧！", 97);
		Say("杨影枫：啊……", 4);
		Goto @end;
	@Event168:
		Say("阿亮他妈：公子小心？", 97);
		Goto @end;
	@Event170:
		If ($ALiangTaMa == 1) @ALiangTaMa01;
		If ($ALiangTaMa == 2) @ALiangTaMa02;
		If ($ALiangTaMa == 3) @ALiangTaMa03;
		@ALiangTaMa01:
			Say("阿亮他妈：公子，听说恶少他老爹以前是城里的大官呢，你们可要小心呀！", 97);
			Say("杨影枫：谢谢提醒！", 3);
			Goto @end;
		@ALiangTaMa02:
			Say("阿亮他妈：紫轩姑娘可算是清平乡最漂亮的姑娘了，公子真是有福呀。", 97);
			Goto @end;
		@ALiangTaMa03:
			Say("阿亮他妈：公子还是带紫轩姑娘快离开这里比较好。听说恶少还有一帮朋友叫什么“一点金”的，我记不清楚了，还是赶紧走吧。", 97);
			Goto @end;
		Goto @end;
	@Event230:
		Say("阿亮他妈：好久没有看见公子了。哎呀，紫轩姑娘的脸色好象不太好，是身体不适吗？", 97);
		Say("杨影枫：多谢关心。紫轩要在清平乡家里小住一阵，麻烦你多多照顾她。", 2);
		Say("阿亮他妈：没问题，公子你放心！", 97);
		Say("杨影枫：多谢你了。", 2);
		Goto @end;
	@Event231232:
		Say("阿亮他妈：公子放心，紫轩姑娘不会有事的。", 97);
		Goto @end;
	@Event370:
		Say("阿亮他妈：公子你可回来了，紫轩姑娘她……", 97);
		Say("杨影枫：她怎么了？", 4);
		Say("阿亮他妈：紫轩姑娘突然搬走了，我也不知道她去了哪里。", 97);
		Say("杨影枫：怎么会这样？我先去她家看看。", 2);
		Goto @end;
	@Event375:
		Say("阿亮他妈：紫轩姑娘……找到了吗？", 97);
		Say("杨影枫：她怎么会突然搬走呢？", 2);
		Say("阿亮他妈：我多一句嘴，公子你不要生气，紫轩姑娘她本来就不是清平乡人氏，来得很突然，走得也很突然。", 97);
		Say("杨影枫：多谢提醒！", 2);
		Goto @end;
	Goto @end;

@end:
	Return;

