scripts.清平乡阿亮对话.txt:
	If ($SubEvent08 == 5) @SubEvent085;

	GetRandNum($ALangTalk, 1, 5);
	If ($ALangTalk == 1) @ALangTalk1;
	If ($ALangTalk == 2) @ALangTalk2;
	If ($ALangTalk == 3) @ALangTalk3;
	If ($ALangTalk == 4) @ALangTalk4;
	If ($ALangTalk == 5) @ALangTalk5;
	@ALangTalk1:
		Say("阿亮：大哥哥，这附近好像有兔子。", 87);
		Goto @end;
	@ALangTalk2:
		Say("阿亮：大哥哥，我最喜欢兔子了。", 87);
